using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net;
using System.Net.Http;
using System.Net.Sockets;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

namespace AsterHand {
    internal sealed class ChatGPTAuth : IDisposable {
        const string Origin="https://auth.openai.com",Resource="https://api.openai.com/v1";
        readonly Vault vault;readonly SemaphoreSlim exchange=new SemaphoreSlim(1),refresh=new SemaphoreSlim(1);
        CancellationTokenSource pending;Dictionary<string,object> attempt;TcpListener listener;
        public Func<string,object,bool,CancellationToken,Task<Dictionary<string,object>>> Transport {get;set;}
        public string AuthorizationUrl {get;private set;}
        public event Action<string> Completed;
        public ChatGPTAuth(Vault v) {vault=v;lock(v.Sync){if(J.Str(v.State,"chatgptHostId").Length==0){v.State["chatgptHostId"]="urn:uuid:"+J.Id();v.Save();}}}
        public List<object> Profiles {get{lock(vault.Sync)return J.List(J.Get(vault.State,"chatgptProfiles"));}}
        public object Selected {get{return Profiles.FirstOrDefault(p=>J.Str(p,"id")==J.Str(vault.State,"selectedChatgpt"));}}
        public static bool PlanEnabled(object profile) {return profile!=null&&J.Str(profile,"scope").Split(' ').Contains("chatgpt.tokens.use.direct");}
        public void Select(string id) {if(!Profiles.Any(p=>J.Str(p,"id")==id))throw new Exception("ChatGPT 账户不存在。");lock(vault.Sync){vault.State["selectedChatgpt"]=id;vault.Save();}}
        static string Form(object value) {return string.Join("&",J.Map(value).Select(kv=>Uri.EscapeDataString(kv.Key)+"="+Uri.EscapeDataString(Convert.ToString(kv.Value))));}
        static bool AuthUrl(string url) {Uri u;return Uri.TryCreate(url,UriKind.Absolute,out u)&&u.Scheme=="https"&&u.Host=="auth.openai.com"&&u.IsDefaultPort&&u.UserInfo.Length==0&&u.Fragment.Length==0;}
        async Task<Dictionary<string,object>> Send(string url,object body,bool form,CancellationToken ct) {if(!AuthUrl(url))throw new Exception("OAuth 请求地址无效。");if(Transport!=null)return await Transport(url,body,form,ct).ConfigureAwait(false);using(var client=Net.Client(30))using(var req=new HttpRequestMessage(body==null?HttpMethod.Get:HttpMethod.Post,url)){if(body!=null)req.Content=new StringContent(form?Form(body):J.Write(body),Encoding.UTF8,form?"application/x-www-form-urlencoded":"application/json");using(var response=await client.SendAsync(req,HttpCompletionOption.ResponseHeadersRead,ct).ConfigureAwait(false)){string text=await Net.ReadText(response.Content,1024*1024,ct).ConfigureAwait(false);if(!response.IsSuccessStatusCode)throw new Exception("ChatGPT 授权服务请求失败（HTTP "+(int)response.StatusCode+"）。请重新登录。");return string.IsNullOrWhiteSpace(text)?J.Obj():J.Read(text);}}}
        public string Begin(bool newAccount,bool includeHints=true,bool requestConsent=false) {Cancel();pending=new CancellationTokenSource(TimeSpan.FromMinutes(10));listener=new TcpListener(IPAddress.Loopback,0);listener.Start(4);string redirect="http://127.0.0.1:"+((IPEndPoint)listener.LocalEndpoint).Port+"/auth/callback";var old=newAccount?null:Selected;string client=newAccount?"dynamic_agent_client":J.Str(old,"client_id",J.Str(vault.State,"pendingChatgptClientId","dynamic_agent_client"));if(client.Length==0)client="dynamic_agent_client";string verifier=Wire.B64Url(Wire.Random(32));attempt=J.Obj("id",J.Id(),"state",Wire.B64Url(Wire.Random(32)),"nonce",Wire.B64Url(Wire.Random(32)),"verifier",verifier,"redirect",redirect,"created",J.Now,"client",client,"profile",old);var parameters=J.Obj("client_id",client,"response_type","code","redirect_uri",redirect,"scope","openid profile email offline_access resource.invoke chatgpt.tokens.use.direct","resource",Resource,"state",J.Str(attempt,"state"),"nonce",J.Str(attempt,"nonce"),"code_challenge_method","S256","code_challenge",Wire.B64Url(Wire.Hash(Wire.Utf8(verifier))),"ext_agent_host_id",J.Str(vault.State,"chatgptHostId"));if(client=="dynamic_agent_client")parameters["agent_name_hint"]="AsterHand";else if(old!=null&&includeHints){if(J.Str(old,"id_token").Length>0)parameters["id_token_hint"]=J.Str(old,"id_token");if(J.Str(old,"email").Length>0)parameters["login_hint"]=J.Str(old,"email");}if(requestConsent)parameters["prompt"]="consent";AuthorizationUrl=Origin+"/api/accounts/authorize?"+Form(parameters);Listen(listener,attempt,pending.Token);return AuthorizationUrl;}
        async void Listen(TcpListener server,Dictionary<string,object> current,CancellationToken ct) {using(ct.Register(()=>{try{server.Stop();}catch{}})){try{while(!ct.IsCancellationRequested){using(var socket=await server.AcceptTcpClientAsync().ConfigureAwait(false))using(var timeout=CancellationTokenSource.CreateLinkedTokenSource(ct)){timeout.CancelAfter(TimeSpan.FromSeconds(8));bool validated=false;try{var stream=socket.GetStream();var data=new List<byte>();while(data.Count<16384){byte[] b=await DeviceHub.ReadExact(stream,1,timeout.Token).ConfigureAwait(false);data.Add(b[0]);int n=data.Count;if(n>=4&&data[n-4]==13&&data[n-3]==10&&data[n-2]==13&&data[n-1]==10)break;}string[] lines=Encoding.ASCII.GetString(data.ToArray()).Split(new[]{"\r\n"},StringSplitOptions.None);string[] first=lines[0].Split(' ');if(data.Count>=16384||first.Length!=3||first[0]!="GET"||!first[1].StartsWith("/auth/callback?"))throw new Exception("回调地址不匹配。");string callback=J.Str(current,"redirect")+first[1].Substring("/auth/callback".Length);ValidateCallback(callback,current);validated=true;timeout.CancelAfter(Timeout.Infinite);await Complete(callback,ct).ConfigureAwait(false);timeout.CancelAfter(TimeSpan.FromSeconds(8));await BrowserReply(stream,true,timeout.Token).ConfigureAwait(false);Notify(PlanEnabled(Selected)?"ChatGPT 登录成功。":"ChatGPT 登录成功，尚未授权套餐用量。");return;}catch(Exception e){try{awaitResult(socket.GetStream(),false,timeout.Token);}catch{}if(validated){Cancel();Notify(J.Error(e));return;}if(attempt!=current||ct.IsCancellationRequested)return;if(e is OperationCanceledException)continue;/* Reject unrelated or malformed local callbacks without replacing the pending login. */}}}}catch(SocketException){}catch(ObjectDisposedException){}catch(Exception){if(!ct.IsCancellationRequested)Notify("ChatGPT 登录未完成，请重试。");}}}
        static void awaitResult(Stream s,bool ok,CancellationToken ct) {BrowserReply(s,ok,ct).GetAwaiter().GetResult();}
        static async Task BrowserReply(Stream stream,bool ok,CancellationToken ct) {byte[] body=Wire.Utf8(ok?"AsterHand: Sign-in complete. Return to the AsterHand app.":"AsterHand: Sign-in was not completed. Return to the app and retry.");byte[] head=Encoding.ASCII.GetBytes("HTTP/1.1 "+(ok?"200 OK":"400 Bad Request")+"\r\nContent-Type: text/plain; charset=utf-8\r\nCache-Control: no-store\r\nContent-Security-Policy: default-src 'none'; frame-ancestors 'none'\r\nConnection: close\r\nContent-Length: "+body.Length+"\r\n\r\n");await stream.WriteAsync(head,0,head.Length,ct).ConfigureAwait(false);await stream.WriteAsync(body,0,body.Length,ct).ConfigureAwait(false);}
        void Notify(string message) {var callback=Completed;if(callback!=null)callback(message);}
        public static Dictionary<string,object> ValidateCallback(string text,object state) {Uri u,expected;string value=text.Trim();if(!Uri.TryCreate(J.Str(state,"redirect"),UriKind.Absolute,out expected)||!Uri.TryCreate(value,UriKind.Absolute,out u)||u.Scheme!="http"||u.Host!="127.0.0.1"||u.Port!=expected.Port||u.AbsolutePath!="/auth/callback"||u.UserInfo.Length>0||u.Fragment.Length>0||J.Now-J.Num(state,"created")>600)throw new Exception("回调地址不匹配或登录请求已过期。");var query=J.Obj();foreach(string part in u.Query.TrimStart('?').Split('&')){if(part.Length==0)continue;string[] pair=part.Split(new[]{'='},2);string key=Uri.UnescapeDataString(pair[0].Replace('+',' '));if(query.ContainsKey(key))throw new Exception("回调包含重复参数。");query[key]=Uri.UnescapeDataString((pair.Length>1?pair[1]:"").Replace('+',' '));}if(!Wire.Equal(Wire.Utf8(J.Str(query,"state")),Wire.Utf8(J.Str(state,"state")))||J.Str(query,"state").Length==0)throw new Exception("OAuth state 不匹配。");if(J.Str(query,"error").Length>0)throw new Exception("OpenAI 未完成本次授权。");if(J.Str(query,"code").Length==0)throw new Exception("回调没有授权码。");string requested=J.Str(state,"client"),issued=J.Str(query,"client_id");if(requested=="dynamic_agent_client"){if(issued.Length==0||issued=="dynamic_agent_client")throw new Exception("OpenAI 未返回已注册的 client_id。");}else if(issued.Length>0&&issued!=requested)throw new Exception("返回的 client_id 与原账户不匹配。");return query;}
        public async Task Complete(string callback,CancellationToken ct) {await exchange.WaitAsync(ct).ConfigureAwait(false);try{var current=attempt;if(current==null)throw new Exception("请先开始 ChatGPT 登录。");var values=ValidateCallback(callback,current);string client=J.Str(current,"client")=="dynamic_agent_client"?J.Str(values,"client_id"):J.Str(current,"client");lock(vault.Sync){vault.State["pendingChatgptClientId"]=client;vault.Save();}var token=await Send(Origin+"/api/accounts/oauth/token",J.Obj("grant_type","authorization_code","client_id",client,"code",J.Str(values,"code"),"code_verifier",J.Str(current,"verifier"),"redirect_uri",J.Str(current,"redirect"),"resource",Resource),true,ct).ConfigureAwait(false);ValidateTokens(token);var metadata=await Send(Origin+"/.well-known/openid-configuration",null,false,ct).ConfigureAwait(false);string jwks=J.Str(metadata,"jwks_uri");if(!AuthUrl(jwks)||J.Str(metadata,"issuer")!=Origin)throw new Exception("OpenID 服务地址不匹配。");var keys=await Send(jwks,null,false,ct).ConfigureAwait(false);var claims=VerifyIdentity(J.Str(token,"id_token"),client,J.Str(current,"nonce"),J.Str(metadata,"issuer"),keys,J.Now);var old=J.Get(current,"profile");if(old!=null&&(J.Str(old,"sub")!=J.Str(claims,"sub")||J.Str(old,"issuer")!=J.Str(claims,"iss")))throw new Exception("返回的 ChatGPT 账户与当前选择不一致，原登录已保留。");string scope=J.Str(token,"scope");if(attempt!=current||ct.IsCancellationRequested)throw new OperationCanceledException();var profile=J.Obj("id",J.Str(old,"id",J.Id()),"client_id",client,"issuer",J.Str(claims,"iss"),"sub",J.Str(claims,"sub"),"email",J.Str(claims,"email"),"name",J.Str(claims,"name"),"access_token",J.Str(token,"access_token"),"refresh_token",J.Str(token,"refresh_token"),"id_token",J.Str(token,"id_token"),"scope",scope,"expires_at",J.Now+J.Num(token,"expires_in"));lock(vault.Sync){var profiles=Profiles.Where(p=>J.Str(p,"id")!=J.Str(profile,"id")).ToList();profiles.Add(profile);vault.State["chatgptProfiles"]=profiles;vault.State["selectedChatgpt"]=J.Str(profile,"id");vault.State.Remove("pendingChatgptClientId");vault.Save();}attempt=null;try{listener.Stop();}catch{}}finally{exchange.Release();}}
        static void ValidateTokens(object token) {if(J.Str(token,"id_token").Length==0||J.Num(token,"expires_in")<0||J.Num(token,"expires_in")>31536000||J.Str(token,"token_type","Bearer")!="Bearer"||PlanEnabled(token)&&(J.Str(token,"access_token").Length==0||J.Str(token,"refresh_token").Length==0||J.Num(token,"expires_in")<=0))throw new Exception("授权服务没有返回完整的登录凭据。");}
        public static Dictionary<string,object> VerifyIdentity(string jwt,string client,string nonce,string issuer,object jwks,double now) {string[] parts=jwt.Split('.');if(parts.Length!=3||jwt.Length>32768)throw new Exception("ID token 格式无效。");var head=J.Read(Encoding.UTF8.GetString(Wire.Decode(parts[0])));var claims=J.Read(Encoding.UTF8.GetString(Wire.Decode(parts[1])));var key=J.List(J.Get(jwks,"keys")).FirstOrDefault(k=>J.Str(k,"kid")==J.Str(head,"kid")&&J.Str(k,"kid").Length>0);byte[] data=Encoding.ASCII.GetBytes(parts[0]+"."+parts[1]),signature=Wire.Decode(parts[2]);bool valid=false;string alg=J.Str(head,"alg");if(alg=="RS256"&&J.Str(key,"kty")=="RSA"){using(var rsa=new RSACryptoServiceProvider{PersistKeyInCsp=false}){rsa.ImportParameters(new RSAParameters{Modulus=Wire.Decode(J.Str(key,"n")),Exponent=Wire.Decode(J.Str(key,"e"))});valid=rsa.VerifyData(data,CryptoConfig.MapNameToOID("SHA256"),signature);}}else if(alg=="ES256"&&J.Str(key,"kty")=="EC"&&J.Str(key,"crv")=="P-256"){byte[] x=Wire.Decode(J.Str(key,"x")),y=Wire.Decode(J.Str(key,"y"));if(x.Length==32&&y.Length==32&&signature.Length==64)using(var cng=CngKey.Import(Wire.Join(BitConverter.GetBytes(0x31534345),BitConverter.GetBytes(32),x,y),CngKeyBlobFormat.EccPublicBlob))using(var ec=new ECDsaCng(cng)){ec.HashAlgorithm=CngAlgorithm.Sha256;valid=ec.VerifyData(data,signature);}}bool audience=J.Str(claims,"aud")==client||J.List(J.Get(claims,"aud")).Any(a=>Convert.ToString(a)==client);if(!valid||!audience||J.Str(claims,"iss")!=issuer||J.Str(claims,"sub").Length==0||J.Num(claims,"exp")<=now||J.Num(claims,"nbf",now)>now+60||nonce!=null&&J.Str(claims,"nonce")!=nonce)throw new Exception("ID token 签名、身份或有效期校验失败。");return claims;}
        public async Task<string> AccessToken(string profileId,CancellationToken ct) {await refresh.WaitAsync(ct).ConfigureAwait(false);try{var profile=Profiles.FirstOrDefault(p=>J.Str(p,"id")==profileId);if(profile==null)throw new Exception("请先登录 ChatGPT。");if(!J.Str(profile,"scope").Split(' ').Contains("chatgpt.tokens.use.direct"))throw new Exception("当前 ChatGPT 登录未授权套餐用量。");if(J.Num(profile,"expires_at")>J.Now+180)return J.Str(profile,"access_token");var raw=await Send(Origin+"/api/accounts/oauth/token",J.Obj("grant_type","refresh_token","client_id",J.Str(profile,"client_id"),"refresh_token",J.Str(profile,"refresh_token"),"resource",Resource),true,ct).ConfigureAwait(false);if(J.Str(raw,"access_token").Length==0||J.Num(raw,"expires_in")<=0)throw new Exception("ChatGPT 会话刷新失败，请重新登录。");var fresh=J.Read(J.Write(profile));fresh["access_token"]=J.Str(raw,"access_token");fresh["expires_at"]=J.Now+J.Num(raw,"expires_in");if(J.Str(raw,"refresh_token").Length>0)fresh["refresh_token"]=J.Str(raw,"refresh_token");if(J.Get(raw,"scope")!=null)fresh["scope"]=J.Str(raw,"scope");if(!J.Str(fresh,"scope").Split(' ').Contains("chatgpt.tokens.use.direct"))throw new Exception("ChatGPT 套餐用量权限已被撤销。");lock(vault.Sync){vault.State["chatgptProfiles"]=Profiles.Select(p=>J.Str(p,"id")==profileId?fresh:p).ToArray();vault.Save();}return J.Str(fresh,"access_token");}finally{refresh.Release();}}
        public async Task<string> SignOut(string profileId,CancellationToken ct) {Cancel();var profile=Profiles.FirstOrDefault(p=>J.Str(p,"id")==profileId);if(profile==null)return "已退出 ChatGPT。";bool revoked=false;try{var meta=await Send(Origin+"/.well-known/openid-configuration",null,false,ct).ConfigureAwait(false);string endpoint=J.Str(meta,"revocation_endpoint");if(AuthUrl(endpoint)){await Send(endpoint,J.Obj("token",J.Str(profile,"refresh_token"),"token_type_hint","refresh_token","client_id",J.Str(profile,"client_id")),true,ct).ConfigureAwait(false);revoked=true;}}catch{}finally{lock(vault.Sync){var profiles=Profiles.Where(p=>J.Str(p,"id")!=profileId).ToArray();vault.State["chatgptProfiles"]=profiles;if(J.Str(vault.State,"selectedChatgpt")==profileId)vault.State["selectedChatgpt"]=profiles.Length>0?J.Str(profiles[0],"id"):"";vault.Save();}}return revoked?"已退出，并向 OpenAI 撤销登录会话。":"本机登录已移除；OpenAI 未确认远端撤销，可在 ChatGPT 设置中断开 AsterHand。";}
        public void Cancel() {if(pending!=null){pending.Cancel();pending.Dispose();pending=null;}if(listener!=null){try{listener.Stop();}catch{}listener=null;}attempt=null;AuthorizationUrl="";}
        public void Dispose() {Cancel();}
    }
}
